api_contract_examples:
TypeScript example (async iterator + resume):
for await (const item of client.pagedIter({ endpoint: 'responses', pageSize: 50, cursor: null })) {
  process(item)
}
// resume
for await (const item of client.pagedIter({ endpoint: 'responses', cursor: lastCursor })) {
  process(item)
}

Go example (channel-based streaming):
ch := make(chan Response)
go client.StreamResponses(context.Background(), StreamOptions{CheckpointToken: token}, ch)
for r := range ch {
  if r.Checkpoint != "" { save(r.Checkpoint) }
  process(r)
}
